    val disposition_miningValue: Mining_Threat_Retreat_Supervision.ThreatDispositionValue = get_disposition_mining().get
    if(!disposition_mining(disposition_miningValue)) {
      testFailures = testFailures :+ st"'disposition_mining' did not match expected: value of the outgoing data port is ${disposition_miningValue}"
    }
    val disposition_defenseValue: Mining_Threat_Retreat_Supervision.ThreatDispositionValue = get_disposition_defense().get
    if(!disposition_defense(disposition_defenseValue)) {
      testFailures = testFailures :+ st"'disposition_defense' did not match expected: value of the outgoing data port is ${disposition_defenseValue}"
    }
    val disposition_mobilityValue: Mining_Threat_Retreat_Supervision.ThreatDispositionValue = get_disposition_mobility().get
